/* ============================================================================
 * panels/robot_scene/panel.js — the 3D scene panel.
 *
 * Renders whatever scenes/<scene>/scene.json describes — scene bundles are
 * generated by `cramera-onboard` from real coraplex demo runs. Also owns the
 * playback / live controls and the layers overlay.
 *
 * Scene selection: ?scene=<name> URL parameter, else scenes/index.json default.
 *
 * Bus events:
 *   emits    scene:part-clicked {id}   click on a robot part / object
 *   emits    scene:step {step}         playback entered a plan step ('__done__' at end)
 *   emits    live:changed {on, url}    live bridge attached / detached
 *   listens  entity:highlight {ids}    glow the matching 3D objects
 *
 * window.RobotView stays exported for the console and split-resize.
 * ==========================================================================*/
Panels.define('robot-scene', function (root, bus) {
  root.innerHTML =
    '<div class="panel-head">' +
    '  <h2>Semantic Digital Twin Scene</h2>' +
    '  <div class="scene-pickers">' +
    '    <label id="robot-picker" class="scene-picker" style="display:none">Robot:' +
    '      <select id="robot-select" class="scene-select"></select>' +
    '    </label>' +
    '    <label id="environment-picker" class="scene-picker" style="display:none">Environment:' +
    '      <select id="environment-select" class="scene-select"></select>' +
    '    </label>' +
    '    <label id="scene-name-picker" class="scene-picker" style="display:none" title="Every saved scene by name — several can share the same robot and environment (e.g. multiple saved live recordings)">Scene:' +
    '      <select id="scene-name-select" class="scene-select"></select>' +
    '    </label>' +
    '  </div>' +
    '</div>' +
    '<div class="stage">' +
    '  <div id="stage-bg" class="stage-bg"></div>' +
    '  <div id="viewer"></div>' +
    '  <div id="viewer-status" class="viewer-status">Loading scene…</div>' +
    '  <div id="layers-panel" class="layers-panel">' +
    '    <div class="lp-title">Layers</div>' +
    '    <label class="lp-row"><input type="checkbox" id="lyr-objects" checked><span>Bench objects</span></label>' +
    '    <label class="lp-row" title="debug markers the CRAM system publishes (collisions, costmaps, spatial types)"><input type="checkbox" id="lyr-markers" checked><span>ROS markers</span><button id="marker-gear" class="marker-gear" title="marker topics and namespaces">⚙</button></label>' +
    '    <div id="marker-settings" class="marker-settings hidden"></div>' +
    '    <label class="lp-row" title="an axis triad on every frame of the world — URDF links and loose objects (red X, green Y, blue Z)"><input type="checkbox" id="lyr-frames"><span>TF frames</span><button id="frame-gear" class="layer-gear" title="frame axis size and names">⚙</button></label>' +
    '    <div id="frame-settings" class="frame-settings hidden"></div>' +
    '    <label class="lp-row"><input type="checkbox" id="lyr-labels"><span>Object labels</span></label>' +
    '    <label class="lp-row"><input type="checkbox" id="lyr-floor" checked><span>Floor shadow</span></label>' +
    '    <label class="lp-row" title="Attach to a running demo whenever one is reachable — including the next run after this one ends — instead of only once per page"><input type="checkbox" id="lyr-auto-live" checked><span>Auto-attach live</span></label>' +
    '    <div class="lp-legend" id="lp-legend"></div>' +
    '  </div>' +
    '  <div id="live-indicator" class="live-indicator">● LIVE</div>' +
    '  <div id="step-caption" class="step-caption hidden"></div>' +
    '  <div class="stage-hint">drag orbit · scroll zoom · right-drag pan · drag objects &amp; the blue place target</div>' +
    '</div>' +
    '<div class="workflow">' +
    '  <div class="workflow-head"><span class="wf-btns">' +
    '    <button id="live-btn" class="play-btn live" style="display:none" title="Attach to the running demo (cramera-live bridge) — renders the live world instead of the recording">◉ Live</button>' +
    '    <button id="play-btn" class="play-btn cram" title="Play the recorded coraplex + giskardpy motion trajectory">▶ Play robot motion</button>' +
    '    <button id="record-stop-btn" class="play-btn record" style="display:none" title="Stop capturing the live run into a temporary scene you can replay, discard or save">⏹ Stop recording</button>' +
    '    <button id="record-discard-btn" class="play-btn record" style="display:none" title="Discard the captured recording">✕ Discard</button>' +
    '    <button id="record-save-btn" class="play-btn record" style="display:none" title="Save the captured recording as a permanent scene">💾 Save…</button>' +
    '    <select id="playback-speed" class="scene-select" style="display:none" title="Playback speed"></select>' +
    '  </span></div>' +
    '  <div id="playback-scrub-row" class="playback-scrub-row" style="display:none">' +
    '    <div class="playback-track">' +
    '      <input type="range" id="playback-scrubber" class="playback-scrubber" min="0" max="0" step="1" value="0">' +
    '      <div id="timeline-events" class="timeline-events"></div>' +
    '      <div id="timeline-preview" class="timeline-preview hidden"></div>' +
    '    </div>' +
    '    <span id="playback-time" class="playback-time">0:00 / 0:00</span>' +
    '  </div>' +
    '</div>';
  function $(id) { return root.querySelector('#' + id); }

  console.log('%c[cramera] robot-scene panel', 'color:#39d5c8;font-weight:bold');
  const container = $('viewer');
  const statusEl = $('viewer-status');
  const SCENES = 'scenes/';

  //: how often the viewer asks whether a live bridge is reachable, in ms
  const LIVE_PROBE_INTERVAL_MS = 3000;
  //: how long after mount imported materials keep being re-tamed, in seconds
  const MATERIAL_SETTLE_SECONDS = 25;

  const scene3 = new THREE.Scene();
  scene3.background = null;

  const camera = new THREE.PerspectiveCamera(45, 1, 0.01, 200);
  camera.position.set(3, 2.4, 4);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.outputEncoding = THREE.sRGBEncoding;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 0.95;
  container.appendChild(renderer.domElement);

  // soft vertical-gradient studio backdrop
  (function () {
    const cv = document.createElement('canvas');
    cv.width = 2; cv.height = 256;
    const ctx = cv.getContext('2d');
    const g = ctx.createLinearGradient(0, 0, 0, 256);
    g.addColorStop(0, '#232833'); g.addColorStop(0.55, '#151922'); g.addColorStop(1, '#0c0e13');
    ctx.fillStyle = g; ctx.fillRect(0, 0, 2, 256);
    scene3.background = new THREE.CanvasTexture(cv);
  })();

  // image-based lighting (imported .dae lights are stripped on load)
  if (THREE.RoomEnvironment && THREE.PMREMGenerator) {
    try {
      const pmrem = new THREE.PMREMGenerator(renderer);
      scene3.environment = pmrem.fromScene(new THREE.RoomEnvironment(), 0.04).texture;
    } catch (e) { /* optional */ }
  }

  scene3.add(new THREE.HemisphereLight(0xf4efe6, 0x2a2d33, 0.32));
  scene3.add(new THREE.AmbientLight(0xfff4e6, 0.05));
  const key = new THREE.DirectionalLight(0xfff2df, 1.05);
  key.position.set(4, 7, 3);
  key.castShadow = true;
  key.shadow.mapSize.set(4096, 4096);
  key.shadow.camera.near = 0.5; key.shadow.camera.far = 30;
  key.shadow.camera.left = -6; key.shadow.camera.right = 6;
  key.shadow.camera.top = 6; key.shadow.camera.bottom = -6;
  key.shadow.bias = -0.0003;
  key.shadow.normalBias = 0.02;
  key.shadow.radius = 3;
  scene3.add(key);
  const back = new THREE.DirectionalLight(0xdfe6f2, 0.3);
  back.position.set(-4, 4, -3);
  scene3.add(back);

  // %% procedural textures (floor planks)
  function floorTexture() {
    const cv = document.createElement('canvas'); cv.width = 512; cv.height = 512;
    const ctx = cv.getContext('2d');
    ctx.fillStyle = '#b9a184'; ctx.fillRect(0, 0, 512, 512);
    const plank = 512 / 6;
    for (let r = 0; r < 6; r++) {
      const shade = 168 + ((r * 37) % 40) - 20;
      ctx.fillStyle = 'rgb(' + (shade + 20) + ',' + (shade - 4) + ',' + (shade - 30) + ')';
      ctx.fillRect(0, r * plank, 512, plank - 2);
      ctx.strokeStyle = 'rgba(60,40,25,0.35)'; ctx.lineWidth = 2;
      ctx.strokeRect(0, r * plank, 512, plank - 2);
      for (let i = 0; i < 40; i++) {
        ctx.strokeStyle = 'rgba(90,60,40,0.06)';
        const y = r * plank + Math.random() * plank;
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(512, y + (Math.random() - 0.5) * 4); ctx.stroke();
      }
    }
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8;
    return t;
  }
  function woodTexture(base, streak) {
    const cv = document.createElement('canvas'); cv.width = 256; cv.height = 256;
    const ctx = cv.getContext('2d');
    ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 220; i++) {
      const y = Math.floor((i / 220) * 256) + (i % 3);
      ctx.strokeStyle = 'rgba(' + streak + ',' + (0.03 + (i % 5) * 0.015) + ')';
      ctx.lineWidth = 1 + (i % 3);
      ctx.beginPath(); ctx.moveTo(0, y);
      for (let x = 0; x <= 256; x += 16) ctx.lineTo(x, y + Math.sin((x + i) * 0.05) * 1.5);
      ctx.stroke();
    }
    const t = new THREE.CanvasTexture(cv);
    t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 8;
    return t;
  }
  const WOOD_COUNTER = woodTexture('#9c6b3f', '70,45,25');
  const WOOD_TABLE = woodTexture('#b98a52', '90,60,35');

  const floorTex = floorTexture();
  floorTex.repeat.set(12, 12);
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(60, 60),
    new THREE.MeshStandardMaterial({ map: floorTex, roughness: 0.85, metalness: 0.0 })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene3.add(ground);

  const controls = new THREE.OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.08;
  controls.minDistance = 1;
  controls.maxDistance = 25;
  controls.maxPolarAngle = Math.PI * 0.5;

  // z-up (URDF/map) -> three y-up
  const worldRoot = new THREE.Group();
  const markerRoot = new THREE.Group();   // the CRAM debug-marker overlay (/markers)
  worldRoot.add(markerRoot);
  worldRoot.rotation.x = -Math.PI / 2;
  scene3.add(worldRoot);

  let needsRender = true;
  controls.addEventListener('change', function () { needsRender = true; });

  // %% scene
  let SCENE = null;              // scene.json payload
  let sceneBase = null;          // static/scenes/<name>/
  let traj = null;
  const models = [];              // {name, prefix, robot, obj}
  let robotModel = null;          // the bundle's own robot entry
  const objectMeshes = {};       // mesh key ('milk.stl') -> THREE.Group
  const objectLabels = {};       // mesh key -> label sprite
  const liveSpawned = {};        // mesh key -> true for objects added by live mode
  const objectPending = {};      // mesh key -> true while its geometry is loading
  let labelsOn = false;
  const objectIdByKey = {}, objectKeyById = {};
  const _objLoader = new THREE.STLLoader();   // no manager: for live/on-demand loads

  // add one draggable object to the scene (bundle load or live spawn). spec:
  // {id, key, color, meshUrl?, format?  |  box:[x,y,z]  |  shapes:[ShapeSpecs spec]}.
  // Any mesh format the vendored loaders support (stl/obj/dae) works; unknown →
  // placeholder box. `shapes` is how the live bridge publishes an arbitrary world
  // body: every shape with its own local pose, dimensions and colour.
  function addObject(spec) {
    // present, or its mesh is still in flight — the live reconcile runs at 15 Hz
    // and would otherwise re-request the same STL dozens of times before it lands
    if (objectMeshes[spec.key] || objectPending[spec.key]) return;
    objectPending[spec.key] = true;
    objectIdByKey[spec.key] = spec.id;
    objectKeyById[spec.id] = spec.key;
    const mat = new THREE.MeshStandardMaterial({
      color: new THREE.Color(spec.color || '#cccccc'),
      roughness: 0.5, metalness: 0.05, envMapIntensity: 0.7,
    });
    function place(content) {                  // content: Mesh or Object3D
      content.traverse(function (c) {
        if (c.isMesh) {
          c.castShadow = true; c.receiveShadow = true;
          if (spec.tame && c.material && c.material.emissive) c.material.emissive.setRGB(0, 0, 0);
        }
      });
      const g = new THREE.Group();
      g.add(content);
      const box = new THREE.Box3().setFromObject(content);
      const top = isFinite(box.max.z) ? box.max.z : 0.15;
      const label = makeLabel(spec.id.replace(/_/g, ' '), spec.color);
      label.position.z = top + 0.09;
      label.visible = labelsOn;
      g.add(label);
      objectLabels[spec.key] = label;
      objectMeshes[spec.key] = g;
      delete objectPending[spec.key];
      worldRoot.add(g);
      refreshFrameAxes();            // the new object is a frame of its own
      needsRender = true;
    }
    // a recorded box is placed by its centre, like any other body; a fallback
    // placeholder for a mesh that failed to load sits on top of the recorded pose
    function box(scale, centered) {
      const s = scale || [0.06, 0.06, 0.1];
      const geometry = new THREE.BoxGeometry(s[0], s[1], s[2]);
      if (!centered) geometry.translate(0, 0, s[2] / 2);
      place(new THREE.Mesh(geometry, mat));
    }
    // a body published shape by shape: primitives build synchronously, meshes stream
    // into their pose-carrying holders as they load — the group (and so the object's
    // pose updates) exists immediately either way
    function shapeMaterial(shapeSpec) {
      return new THREE.MeshStandardMaterial({
        color: new THREE.Color(shapeSpec.color),
        roughness: 0.5, metalness: 0.05, envMapIntensity: 0.7,
        transparent: shapeSpec.opacity < 1, opacity: shapeSpec.opacity,
      });
    }
    // any relative resource an OBJ/MTL references (the mtllib line, texture maps) is
    // fetched as a side asset of the mesh's own /mesh URL, so a live mesh keeps its
    // authored materials without the bridge serving its whole directory
    function sideAssetModifier(meshUrl) {
      return function (url) {
        if (/^(\/|https?:|data:|blob:)/.test(url)) return url;
        const resource = url.split('/').pop();
        return meshUrl + '&side=' + encodeURIComponent(resource);
      };
    }
    function loadShapeMesh(shapeSpec, holder) {
      const material = shapeMaterial(shapeSpec);
      const fail = function () {
        holder.add(new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, 0.05), material));
        needsRender = true;
      };
      const finish = function (content3d) {
        content3d.scale.set(shapeSpec.scale[0], shapeSpec.scale[1], shapeSpec.scale[2]);
        holder.add(content3d);
        needsRender = true;
      };
      if (shapeSpec.format === 'obj' && THREE.OBJLoader) {
        const manager = new THREE.LoadingManager();
        manager.setURLModifier(sideAssetModifier(shapeSpec.url));
        const loadObj = function (materials) {
          const objLoader = new THREE.OBJLoader(manager);
          if (materials) { materials.preload(); objLoader.setMaterials(materials); }
          objLoader.load(shapeSpec.url, function (o) {
            if (!materials) {
              o.traverse(function (c) { if (c.isMesh) c.material = material; });
            }
            finish(o);
          }, undefined, fail);
        };
        if (shapeSpec.mtl && THREE.MTLLoader) {
          new THREE.MTLLoader(manager).load(shapeSpec.mtl, loadObj,
            undefined, function () { loadObj(null); });
        } else {
          loadObj(null);
        }
      } else if (shapeSpec.format === 'dae' && THREE.ColladaLoader) {
        new THREE.ColladaLoader().load(shapeSpec.url, function (c) { finish(c.scene); },
          undefined, fail);
      } else {
        _objLoader.load(shapeSpec.url, function (geom) {
          finish(new THREE.Mesh(geom, material));
        }, undefined, fail);
      }
    }
    function shapes(shapeSpecs) {
      const content = new THREE.Group();
      shapeSpecs.forEach(function (shapeSpec) {
        const holder = new THREE.Group();
        holder.position.set(shapeSpec.position[0], shapeSpec.position[1], shapeSpec.position[2]);
        holder.quaternion.set(shapeSpec.quaternion[0], shapeSpec.quaternion[1],
          shapeSpec.quaternion[2], shapeSpec.quaternion[3]);
        content.add(holder);
        if (shapeSpec.type === 'box') {
          const s = shapeSpec.size;
          holder.add(new THREE.Mesh(new THREE.BoxGeometry(s[0], s[1], s[2]), shapeMaterial(shapeSpec)));
        } else if (shapeSpec.type === 'cylinder') {
          const geometry = new THREE.CylinderGeometry(shapeSpec.radius, shapeSpec.radius, shapeSpec.height, 24);
          geometry.rotateX(shapeSpec.rotateXDegrees * Math.PI / 180);
          holder.add(new THREE.Mesh(geometry, shapeMaterial(shapeSpec)));
        } else if (shapeSpec.type === 'sphere') {
          holder.add(new THREE.Mesh(new THREE.SphereGeometry(shapeSpec.radius, 24, 16), shapeMaterial(shapeSpec)));
        } else if (shapeSpec.type === 'mesh') {
          loadShapeMesh(shapeSpec, holder);
        }
      });
      place(content);
    }
    if (spec.shapes) { shapes(ShapeSpecs.buildSpecs(spec.shapes, spec.color, spec.liveBase)); return; }
    if (spec.box) { box(spec.box, true); return; }
    const fmt = (spec.format || (spec.meshUrl || '').split('?')[0].split('.').pop() || '').toLowerCase();
    if (fmt === 'obj' && THREE.OBJLoader) {
      new THREE.OBJLoader().load(spec.meshUrl, function (o) {
        o.traverse(function (c) { if (c.isMesh) c.material = mat; });
        place(o);
      }, undefined, function () { box(); });
    } else if (fmt === 'dae' && THREE.ColladaLoader) {
      spec.tame = true;                         // dae carries its own (possibly glowing) materials
      new THREE.ColladaLoader().load(spec.meshUrl, function (c) { place(c.scene); },
        undefined, function () { box(); });
    } else {
      _objLoader.load(spec.meshUrl, function (geom) { place(new THREE.Mesh(geom, mat)); },
        undefined, function () { box(); });
    }
  }
  function removeObject(key) {
    const g = objectMeshes[key];
    if (!g) return;
    worldRoot.remove(g);
    g.traverse(function (c) {
      if (c.geometry) c.geometry.dispose();
      if (c.material) { c.material.map && c.material.map.dispose(); c.material.dispose(); }
    });
    delete objectMeshes[key]; delete objectLabels[key];
    delete objectIdByKey[key]; delete liveSpawned[key]; delete objectPending[key];
    refreshFrameAxes();              // its frame goes with it
  }

  // canvas-sprite name tag, colour-dotted to match the object
  function makeLabel(text, color) {
    const pad = 16, fs = 34, dot = 22;
    const cv = document.createElement('canvas');
    let ctx = cv.getContext('2d');
    ctx.font = '600 ' + fs + 'px Inter, sans-serif';
    cv.width = ctx.measureText(text).width + pad * 2 + dot + 10;
    cv.height = fs + pad * 2;
    ctx = cv.getContext('2d');
    ctx.font = '600 ' + fs + 'px Inter, sans-serif';
    ctx.fillStyle = 'rgba(10,17,32,0.82)';
    const r = 12, w = cv.width, h = cv.height;
    ctx.beginPath();
    ctx.moveTo(r, 0); ctx.arcTo(w, 0, w, h, r); ctx.arcTo(w, h, 0, h, r);
    ctx.arcTo(0, h, 0, 0, r); ctx.arcTo(0, 0, w, 0, r); ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(57,213,200,0.5)'; ctx.lineWidth = 2; ctx.stroke();
    ctx.fillStyle = color || '#39d5c8';
    ctx.beginPath(); ctx.arc(pad + dot / 2, h / 2, dot / 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#e8eefb'; ctx.textBaseline = 'middle';
    ctx.fillText(text, pad + dot + 10, h / 2);
    const tex = new THREE.CanvasTexture(cv);
    tex.anisotropy = 4;
    const spr = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
    const s = 0.0016;
    spr.scale.set(cv.width * s, cv.height * s, 1);
    return spr;
  }
  let linkToPart = {};           // link name -> part name (from robot.parts)
  const readyCbs = [];
  let finalized = false;

  const manager = new THREE.LoadingManager();
  function makeUrdfLoader() {
    const loader = new URDFLoader(manager);
    loader.packages = {};
    loader.parseCollision = false;
    const def = loader.defaultMeshLoader.bind(loader);
    loader.loadMeshCb = function (path, mgr, done) {
      if (/\.obj$/i.test(path)) {
        // an .obj's per-face materials (fabric textures, plastic vs. screen colors)
        // live in its companion .mtl — load that first so a multi-material mesh does
        // not fall back to a single flat grey
        const loadObj = function (materials) {
          const objLoader = new THREE.OBJLoader(mgr);
          if (materials) { materials.preload(); objLoader.setMaterials(materials); }
          objLoader.load(path, function (o) { done(o); },
            undefined, function () { done(new THREE.Object3D()); });
        };
        new THREE.MTLLoader(mgr).load(path.replace(/\.obj$/i, '.mtl'), loadObj,
          undefined, function () { loadObj(null); });
      } else if (/\.dae$/i.test(path)) {
        // ColladaLoader auto-rotates Z_UP assets for standalone use; a URDF mesh must
        // stay in its raw frame, since the world root already applies that correction
        // once for the whole tree — keep the unit scale, undo the rotation
        new THREE.ColladaLoader(mgr).load(path, function (c) {
          done(ColladaMeshUtil.neutralizeUpAxisRotation(c.scene));
        }, undefined, function () { done(new THREE.Object3D()); });
      } else {
        def(path, mgr, done);
      }
    };
    return loader;
  }

  const LIVE_SCENE_NAME = LiveMode.SCENE_NAME;
  // the landing page (no explicit ?scene=) auto-attaches to a live demo the moment
  // one is reachable, instead of requiring a manual click; a URL that names a
  // specific recorded scene is a deliberate choice and is never overridden by this
  const noExplicitScene = !SceneContext.name();
  let autoAttachedLive = false;

  fetch(SCENES + 'index.json')
    .then(function (r) { return r.ok ? r.json() : { default: null, scenes: [] }; })
    .catch(function () { return { default: null, scenes: [] }; })
    .then(function (index) {
      const name = SceneContext.name() || index.default;
      wireScenePickers(index.scenes || [], name);
      if (!name) {
        if (statusEl) statusEl.textContent = 'No scene found — run cramera-onboard first.';
        return;
      }
      sceneBase = SCENES + name + '/';
      return fetch(sceneBase + 'scene.json').then(function (r) { return r.json(); }).then(loadScene);
    })
    .catch(function (e) {
      if (statusEl) statusEl.textContent = 'Scene failed to load: ' + e;
    });

  // header dropdowns: a robot and an environment jointly resolve to the one
  // onboarded scene bundle recorded for that pair (ScenePicker) — there is no
  // independent robot/environment mixing, only a lookup among what was actually
  // recorded, so picking either one narrows the other to valid combinations and
  // always lands on a real scene.
  function wireScenePickers(scenes, activeName) {
    const robotSel = $('robot-select'), envSel = $('environment-select');
    const robotPicker = $('robot-picker'), envPicker = $('environment-picker');
    const nameSel = $('scene-name-select'), namePicker = $('scene-name-picker');
    if (!robotSel || !envSel) return;
    // picking any dropdown navigates away from the live or recording scene, which
    // the dropdowns should never do while watching or capturing a running demo
    if (activeName === LIVE_SCENE_NAME || RecordingMode.isRecordingScene(activeName)) return;

    // a picker with nothing to choose (one option, or none) stays visible but
    // disabled — it disappearing/reappearing as another picker changes would
    // shift the header layout around under the user's cursor
    function fillSelect(sel, values, selected) {
      sel.innerHTML = values.map(function (v) {
        const value = v || '';
        const label = v || '(bench only)';
        return '<option value="' + value + '"' + (value === (selected || '') ? ' selected' : '') + '>' + label + '</option>';
      }).join('');
      sel.disabled = values.length <= 1;
    }

    // Scene: every scene by name, independent of the robot/environment axes below.
    // sceneFor() only ever resolves a (robot, environment) pair to its *first* match,
    // so this is the exhaustive picker for choosing among several scenes that share
    // one — e.g. multiple saved live recordings of the same demo.
    const allNames = ScenePicker.names(scenes);
    if (nameSel && namePicker && allNames.length > 1) {
      namePicker.style.display = '';
      fillSelect(nameSel, allNames, activeName);
      nameSel.addEventListener('change', function () {
        window.location.search = '?scene=' + encodeURIComponent(nameSel.value);
      });
    }

    const robots = ScenePicker.robots(scenes);
    if (robots.length < 2 && ScenePicker.environments(scenes, robots[0]).length < 2) return;
    const active = ScenePicker.describe(scenes, activeName) || {};
    let robot = active.robot || robots[0];

    function navigateTo(environment) {
      const target = ScenePicker.sceneFor(scenes, robot, environment || null);
      if (target) window.location.search = '?scene=' + encodeURIComponent(target);
    }

    if (robotPicker) robotPicker.style.display = '';
    if (envPicker) envPicker.style.display = '';
    fillSelect(robotSel, robots, robot);
    fillSelect(envSel, ScenePicker.environments(scenes, robot), active.environment);

    robotSel.addEventListener('change', function () {
      robot = robotSel.value;
      fillSelect(envSel, ScenePicker.environments(scenes, robot), null);
      navigateTo(envSel.value);
    });
    envSel.addEventListener('change', function () { navigateTo(envSel.value); });
  }

  function loadScene(sc) {
    SCENE = sc;
    playbackSpeedMultiplier = 1;
    if (statusEl) statusEl.textContent = 'Loading ' + sc.name + '…';
    // robot part lookup (link -> part name)
    linkToPart = {};
    const parts = (sc.robot && sc.robot.parts) || {};
    for (const part in parts) parts[part].forEach(function (l) { linkToPart[l] = part; });

    sc.models.forEach(function (m) {
      makeUrdfLoader().load(sceneBase + m.urdf, function (obj) {
        const entry = { name: m.name, prefix: m.prefix || '', robot: !!m.robot, obj: obj };
        models.push(entry);
        if (m.robot) robotModel = entry;
        worldRoot.add(obj);
        refreshFrameAxes();          // every link of the model is a frame
        needsRender = true;
      });
    });

    (sc.objects || []).forEach(function (o) {
      addObject({
        id: o.id, key: o.key, color: o.color,
        box: o.box || null,
        meshUrl: o.mesh ? sceneBase + o.mesh : null,
      });
    });

    buildMarker(sc.placeTarget);
    manager.onLoad = function () {
      upgradeMaterials();
      if (!finalized) finalize();
      needsRender = true;
    };
    [1500, 4000, 9000, 13000].forEach(function (ms) {
      setTimeout(function () {
        if (models.length) { upgradeMaterials(); dropGroundToScene(); needsRender = true; }
      }, ms);
    });
    setTimeout(function () { if (models.length) finalize(); }, 15000);
  }

  function finalize() {
    if (finalized) return;
    finalized = true;
    upgradeMaterials();
    dropGroundToScene();
    fetch(sceneBase + (SCENE.trajectory || 'trajectory.json'))
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        traj = d;
        setupTransports();
        if (traj) applyFrame(0);
        frameCamera();
        if (statusEl) statusEl.classList.add('hidden');
        readyCbs.forEach(function (cb) { cb(); });
        needsRender = true;
      }).catch(function () {
        frameCamera();
        if (statusEl) statusEl.classList.add('hidden');
        readyCbs.forEach(function (cb) { cb(); });
      });
  }

  // %% materials (identical treatment to the hand-built version)
  // guards against imported materials that break the scene's lighting (self-glowing
  // exports, blown-out whites, mirror metals) while leaving authored looks — colors,
  // satin and metallic finishes — as the model ships them
  function tameMat(mat) {
    if (!mat) return;
    if (mat.emissive) mat.emissive.setRGB(0, 0, 0);
    mat.emissiveIntensity = 0;
    if (mat.color) {
      const lum = (mat.color.r + mat.color.g + mat.color.b) / 3;
      if (lum > 0.97) mat.color.setRGB(0.9, 0.9, 0.91);
    }
    if (mat.isMeshPhongMaterial) { mat.shininess = 25; if (mat.specular) mat.specular.setRGB(0.05, 0.05, 0.05); }
    if ('roughness' in mat) mat.roughness = Math.min(Math.max(mat.roughness || 0.7, 0.25), 0.95);
    if ('metalness' in mat) mat.metalness = Math.min(mat.metalness || 0, 0.85);
    if ('envMapIntensity' in mat) mat.envMapIntensity = 0.45;
    mat.needsUpdate = true;
  }
  function linkNameOf(c) {
    let o = c;
    while (o) { if (o.isURDFLink && o.name) return String(o.name); o = o.parent; }
    return '';
  }
  // furniture palette, keyed on common link-name vocabulary via EnvironmentTheme —
  // applies to any environment model; unmatched links keep their tamed authored look
  const THEME_TEXTURES = { counter: WOOD_COUNTER, table: WOOD_TABLE };
  function themeEnvironment(mat, link) {
    tameMat(mat);
    const look = window.EnvironmentTheme.lookOf(link);
    if (look) {
      mat.color.setHex(look.color);
      mat.map = look.texture ? THEME_TEXTURES[look.texture] : null;
      mat.roughness = look.roughness;
      mat.metalness = look.metalness;
    }
    mat.needsUpdate = true;
  }
  const OWN_LIGHTS = new Set();
  scene3.traverse(function (c) { if (c.isLight) OWN_LIGHTS.add(c); });
  function stripImportedLights(root) {
    const kill = [];
    root.traverse(function (c) { if (c.isLight && !OWN_LIGHTS.has(c)) kill.push(c); });
    kill.forEach(function (l) { if (l.parent) l.parent.remove(l); });
  }
  function tameModel(entry) {
    stripImportedLights(entry.obj);
    entry.obj.traverse(function (c) {
      if (!c.isMesh || c.userData._tamed) return;
      c.castShadow = true; c.receiveShadow = true;
      const link = entry.robot ? '' : linkNameOf(c);
      const mats = Array.isArray(c.material) ? c.material : [c.material];
      mats.forEach(function (m) { entry.robot ? tameMat(m) : themeEnvironment(m, link); });
      c.userData._tamed = true;
    });
  }
  function upgradeMaterials() { models.forEach(tameModel); }

  function dropGroundToScene() {
    const envs = models.filter(function (m) { return !m.robot; });
    if (!envs.length) return;
    const box = new THREE.Box3();
    envs.forEach(function (m) { box.expandByObject(m.obj); });
    if (!isFinite(box.min.y) || !isFinite(box.min.x)) return;
    const w = (box.max.x - box.min.x) + 0.4;
    const d = (box.max.z - box.min.z) + 0.4;
    ground.geometry.dispose();
    ground.geometry = new THREE.PlaneGeometry(w, d);
    ground.position.set((box.min.x + box.max.x) / 2, box.min.y + 0.002, (box.min.z + box.max.z) / 2);
    floorTex.repeat.set(w / 0.6, d / 0.6);
    floorTex.needsUpdate = true;
    needsRender = true;
  }

  // %% playback
  let playing = false, playhead = 0, stepCb = function () {}, playbackSpeedMultiplier = 1;
  let lastStep = null;
  const playheadCbs = [];        // notified whenever the playhead moves (autoplay or a seek)
  const _p0 = new THREE.Vector3(), _p1 = new THREE.Vector3();
  const _q0 = new THREE.Quaternion(), _q1 = new THREE.Quaternion();

  function setPose(obj, a, b, t) {
    _p0.set(a[0], a[1], a[2]); _p1.set(b[0], b[1], b[2]);
    obj.position.copy(_p0).lerp(_p1, t);
    _q0.set(a[3], a[4], a[5], a[6]); _q1.set(b[3], b[4], b[5], b[6]);
    obj.quaternion.copy(_q0).slerp(_q1, t);
  }
  function applyFrame(f) {
    if (!traj) return;
    const F = traj.frames, i0 = Math.floor(f), i1 = Math.min(i0 + 1, F.length - 1), t = f - i0;
    const f0 = F[i0], f1 = F[i1];
    for (const k in f0) {
      const j = JointRouting.jointFor(models, k);
      if (j) j.setJointValue(f0[k] + ((f1[k] !== undefined ? f1[k] : f0[k]) - f0[k]) * t);
    }
    if (robotModel && traj.base && traj.base[i0]) {
      setPose(robotModel.obj, traj.base[i0], traj.base[i1] || traj.base[i0], t);
      const bo = baseOffsetAt(f);
      robotModel.obj.position.x += bo.x; robotModel.obj.position.y += bo.y;
    }
    if (traj.objects) {
      const o0 = traj.objects[i0], o1 = traj.objects[i1];
      for (const name in objectMeshes) {
        if (o0[name] && o1[name]) {
          setPose(objectMeshes[name], o0[name], o1[name], t);
          const oo = objOffsetAt(name, f);
          objectMeshes[name].position.x += oo.x;
          objectMeshes[name].position.y += oo.y;
          // while the object is still resting (before its pick), hold the
          // dragged surface height so it doesn't float / clip
          const pd = pickDeltas[name];
          if (pd && pd.zAbs != null && restingBeforePick(name, f)) {
            objectMeshes[name].position.z = pd.zAbs;
          }
        }
      }
    }
    if (SCENE && SCENE.segments) {
      const seg = SCENE.segments.find(function (s) { return i0 >= s.start && i0 < s.end; });
      if (seg && seg.step !== lastStep) { lastStep = seg.step; stepCb(seg.step); }
    }
  }

  // %% timeline previews
  // What the scene looks like at one recorded frame, as a data URL. Rendered into an
  // off-screen target rather than the canvas, so the live view neither flickers nor
  // has to keep its drawing buffer around; the playhead is put back afterwards.
  const THUMBNAIL_WIDTH = 172;
  const THUMBNAIL_HEIGHT = 104;
  const thumbnails = {};

  function thumbnailAt(frame) {
    if (!traj) return null;
    if (thumbnails[frame]) return thumbnails[frame];
    const target = new THREE.WebGLRenderTarget(THUMBNAIL_WIDTH, THUMBNAIL_HEIGHT);
    const restore = playhead;
    const aspect = camera.aspect;
    applyFrame(frame);
    camera.aspect = THUMBNAIL_WIDTH / THUMBNAIL_HEIGHT;
    camera.updateProjectionMatrix();
    renderer.setRenderTarget(target);
    renderer.render(scene3, camera);
    const pixels = new Uint8Array(THUMBNAIL_WIDTH * THUMBNAIL_HEIGHT * 4);
    renderer.readRenderTargetPixels(target, 0, 0, THUMBNAIL_WIDTH, THUMBNAIL_HEIGHT, pixels);
    renderer.setRenderTarget(null);
    target.dispose();
    camera.aspect = aspect;
    camera.updateProjectionMatrix();
    applyFrame(restore);
    needsRender = true;
    thumbnails[frame] = pixelsToDataUrl(pixels);
    return thumbnails[frame];
  }

  // GL reads bottom-up, a canvas draws top-down
  function pixelsToDataUrl(pixels) {
    const canvas = document.createElement('canvas');
    canvas.width = THUMBNAIL_WIDTH;
    canvas.height = THUMBNAIL_HEIGHT;
    const context = canvas.getContext('2d');
    const image = context.createImageData(THUMBNAIL_WIDTH, THUMBNAIL_HEIGHT);
    const rowBytes = THUMBNAIL_WIDTH * 4;
    for (let row = 0; row < THUMBNAIL_HEIGHT; row++) {
      const source = (THUMBNAIL_HEIGHT - row - 1) * rowBytes;
      image.data.set(pixels.subarray(source, source + rowBytes), row * rowBytes);
    }
    context.putImageData(image, 0, 0);
    return canvas.toDataURL('image/png');
  }

  function playTrajectory() {
    if (!traj) return false;
    // resume from wherever the playhead sits (including a manual seek); only an
    // already-finished playthrough restarts from the beginning
    if (playhead >= traj.frames.length - 1) { playhead = 0; lastStep = null; }
    playing = true;
    return true;
  }
  function stopTrajectory() { playing = false; }

  function seekTo(frame) {
    if (!traj) return;
    playhead = Math.max(0, Math.min(frame, traj.frames.length - 1));
    lastStep = null;   // re-evaluate the step caption even when seeking backward
    applyFrame(playhead);
    playheadCbs.forEach(function (cb) { cb(playhead); });
    needsRender = true;
  }

  // %% adjustable pick spawns + place target
  // The scene records for each manipulation segment which object moves and its
  // attach/detach frames — no detection heuristics needed here.
  const pickDeltas = {};         // mesh key -> {x,y}
  const placeDelta = { x: 0, y: 0 };
  const ZERO = { x: 0, y: 0 };
  let PLACE0 = null;
  let transports = [];
  const spawn0 = {};

  function smooth(u) { u = Math.min(1, Math.max(0, u)); return u * u * (3 - 2 * u); }

  function setupTransports() {
    transports = [];
    if (!SCENE || !traj) return;
    (SCENE.objects || []).forEach(function (o) {
      pickDeltas[o.key] = { x: 0, y: 0, zAbs: null };
      spawn0[o.key] = o.spawn.slice();
    });
    (SCENE.segments || []).forEach(function (s) {
      if (!s.picks || s.attach === undefined || s.detach === undefined) return;
      const key = objectKeyById[s.picks];
      if (key) transports.push({ obj: key, start: s.start, end: s.end, attach: s.attach, detach: s.detach });
    });
  }

  function restingBeforePick(name, f) {
    for (let k = 0; k < transports.length; k++) {
      if (transports[k].obj === name) return f < transports[k].attach;
    }
    return true;   // never picked → always resting
  }

  function objOffsetAt(name, f) {
    for (let k = 0; k < transports.length; k++) {
      const tr = transports[k];
      if (tr.obj !== name) continue;
      const pd = pickDeltas[name] || ZERO;
      if (f < tr.attach) return pd;
      if (f < tr.detach) {
        const u = smooth((f - tr.attach) / (tr.detach - tr.attach));
        return { x: pd.x + (placeDelta.x - pd.x) * u, y: pd.y + (placeDelta.y - pd.y) * u };
      }
      return placeDelta;
    }
    return pickDeltas[name] || ZERO;
  }
  function baseOffsetAt(f) {
    for (let k = 0; k < transports.length; k++) {
      const tr = transports[k];
      if (f < tr.start || f >= tr.end) continue;
      const pd = pickDeltas[tr.obj] || ZERO;
      if (f < tr.attach) {
        const w = smooth((f - tr.start) / Math.max(1, tr.attach - tr.start));
        return { x: pd.x * w, y: pd.y * w };
      }
      if (f < tr.detach) {
        const u = smooth((f - tr.attach) / (tr.detach - tr.attach));
        return { x: pd.x + (placeDelta.x - pd.x) * u, y: pd.y + (placeDelta.y - pd.y) * u };
      }
      const w2 = 1 - smooth((f - tr.detach) / Math.max(1, tr.end - tr.detach));
      return { x: placeDelta.x * w2, y: placeDelta.y * w2 };
    }
    return ZERO;
  }

  // %% camera
  let follow = true;
  const _target = new THREE.Vector3(), _base = new THREE.Vector3();
  function frameCamera() {
    if (!robotModel) return;
    const box = new THREE.Box3().setFromObject(robotModel.obj);
    const c = box.getCenter(new THREE.Vector3());
    controls.target.copy(c);
    camera.position.set(c.x + 3.2, c.y + 1.6, c.z + 3.4);
    controls.update();
    needsRender = true;
  }
  function robotCenter(out) {
    if (!robotModel) return false;
    robotModel.obj.getWorldPosition(_base);
    out.copy(_base); out.y += 0.6;
    return true;
  }

  // %% place-target marker (blue corner brackets)
  const marker = new THREE.Group();
  let MARKER_LIMIT = null;
  function buildMarker(pt) {
    if (!pt) { marker.visible = false; return; }
    const blue = 0x35a7ff;
    const barMat = new THREE.MeshBasicMaterial({ color: blue });
    const hx = 0.30, hy = 0.22, L = 0.14, W = 0.022, H = 0.012;
    [[-1, -1], [1, -1], [-1, 1], [1, 1]].forEach(function (c) {
      const armX = new THREE.Mesh(new THREE.BoxGeometry(L, W, H), barMat);
      armX.position.set(c[0] * (hx - L / 2), c[1] * hy, 0);
      const armY = new THREE.Mesh(new THREE.BoxGeometry(W, L, H), barMat);
      armY.position.set(c[0] * hx, c[1] * (hy - L / 2), 0);
      marker.add(armX, armY);
    });
    const fill = new THREE.Mesh(
      new THREE.PlaneGeometry(hx * 2, hy * 2),
      new THREE.MeshBasicMaterial({ color: blue, transparent: true, opacity: 0.08, depthWrite: false })
    );
    marker.add(fill);
    PLACE0 = { x: pt.position[0], y: pt.position[1] };
    MARKER_LIMIT = pt.bounds;
    marker.position.set(PLACE0.x, PLACE0.y, pt.z);
    worldRoot.add(marker);
  }

  // %% drag + click-to-inspect
  const dragRay = new THREE.Raycaster(), dragNdc = new THREE.Vector2();
  const dragStartNdc = new THREE.Vector2(), dragStartWorld = new THREE.Vector3();
  const camR = new THREE.Vector3(), camF = new THREE.Vector3(), camU = new THREE.Vector3();
  const _w = new THREE.Vector3();
  let dragTarget = null, dragging = false;
  let clickX = 0, clickY = 0, clickArmed = false;
  let partClickCb = null;

  function objLimit() {
    return (SCENE && SCENE.dragBounds) || { minX: -50, maxX: 50, minY: -50, maxY: 50 };
  }
  function pointerNdc(e) {
    const r = renderer.domElement.getBoundingClientRect();
    dragNdc.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
  }
  function draggableMeshes() {
    const list = [];
    for (const n in objectMeshes) {
      objectMeshes[n].traverse(function (c) { if (c.isMesh) { c.userData.simObj = n; list.push(c); } });
    }
    if (marker.visible !== false) {
      marker.traverse(function (c) { if (c.isMesh) { c.userData.simMarker = true; list.push(c); } });
    }
    return list;
  }
  function pickDraggable(e) {
    pointerNdc(e);
    dragRay.setFromCamera(dragNdc, camera);
    const hits = dragRay.intersectObjects(draggableMeshes(), false);
    if (!hits.length) return null;
    const o = hits[0].object;
    if (o.userData.simMarker) return { group: marker, marker: true };
    return { group: objectMeshes[o.userData.simObj], name: o.userData.simObj };
  }

  // %% surface snapping: rest a dragged object on whatever is beneath it
  // cast a ray straight down through the object and drop it onto the highest
  // surface (table, counter, another object, else the floor) — never floating.
  const DOWN = new THREE.Vector3(0, -1, 0);
  const _ray = new THREE.Raycaster();
  let _envMeshes = null;
  function envMeshes() {
    if (_envMeshes) return _envMeshes;
    _envMeshes = [];
    models.forEach(function (m) {
      if (m.robot) return;
      m.obj.traverse(function (c) { if (c.isMesh) _envMeshes.push(c); });
    });
    if (ground) _envMeshes.push(ground);
    return _envMeshes;
  }
  function meshBox(group) {                 // world AABB over the object's meshes only (skip label sprite)
    const box = new THREE.Box3(); box.makeEmpty();
    group.traverse(function (c) { if (c.isMesh) box.expandByObject(c); });
    return box;
  }
  function surfaceTargets(excludeKey) {     // env + floor + the OTHER objects
    const targets = envMeshes().slice();
    for (const k in objectMeshes) {
      if (k !== excludeKey && objectMeshes[k].visible) {
        objectMeshes[k].traverse(function (o) { if (o.isMesh) targets.push(o); });
      }
    }
    return targets;
  }
  // cursor -> world point on the horizontal drag plane (infinite, so the object
  // follows the cursor anywhere — the surface height is fixed afterwards by
  // snapToSurface). The plane is set through the grab point on pointerdown.
  const _dragPlane = new THREE.Plane();
  const _hitPt = new THREE.Vector3();
  function surfacePointAt(e) {
    pointerNdc(e);
    _ray.setFromCamera(dragNdc, camera);
    return _ray.ray.intersectPlane(_dragPlane, _hitPt) ? _hitPt.clone() : null;
  }
  function snapToSurface(group, excludeKey) {
    const box = meshBox(group);
    if (!isFinite(box.min.y)) return;
    const c = box.getCenter(new THREE.Vector3());
    _ray.set(new THREE.Vector3(c.x, box.max.y + 0.5, c.z), DOWN);
    _ray.far = 6;
    const hits = _ray.intersectObjects(surfaceTargets(excludeKey), false);
    if (!hits.length) return;
    group.position.z += hits[0].point.y - box.min.y;   // worldRoot: +local z == +world y
  }

  renderer.domElement.addEventListener('pointerdown', function (e) {
    if (e.button !== 0) return;
    clickX = e.clientX; clickY = e.clientY; clickArmed = true;
    if (playing) return;
    const p = pickDraggable(e);
    if (!p) return;
    if (liveOn && p.marker) return;    // the place marker has no meaning live
    dragTarget = p; dragging = true;
    controls.enabled = false;
    renderer.domElement.setPointerCapture(e.pointerId);
    renderer.domElement.style.cursor = 'grabbing';
    dragStartNdc.copy(dragNdc);
    p.group.getWorldPosition(dragStartWorld);
    // horizontal drag plane through the grabbed thing (world y-up)
    _dragPlane.setFromNormalAndCoplanarPoint(new THREE.Vector3(0, 1, 0), dragStartWorld);
    e.preventDefault();
  });
  renderer.domElement.addEventListener('pointermove', function (e) {
    if (!dragging) {
      if (!playing && e.buttons === 0)
        renderer.domElement.style.cursor = pickDraggable(e) ? 'grab' : '';
      return;
    }
    // object drag: the object follows the cursor onto whatever surface it points
    // at (no relative screen mapping, so no artificial reach limit)
    if (dragTarget.name) {
      const key = dragTarget.name, g = objectMeshes[key];
      const hit = surfacePointAt(e);             // world point on the drag plane
      if (hit) {
        worldRoot.worldToLocal(hit);             // map frame (z-up)
        g.position.x = hit.x; g.position.y = hit.y;
        snapToSurface(g, key);                   // exact rest height for this object
        if (liveOn) {
          liveDraggedKey = key;
          postLiveMove(key, g.position.x, g.position.y, g.position.z, false);
        } else {
          const s0 = spawn0[key];
          if (s0 && pickDeltas[key]) {
            pickDeltas[key].x = g.position.x - s0[0];
            pickDeltas[key].y = g.position.y - s0[1];
            pickDeltas[key].zAbs = g.position.z; // held until the recorded pick
          }
          if (traj) applyFrame(playhead);
        }
      }
      needsRender = true;
      return;
    }
    // %% marker drag: camera-basis mapping, clamped to the table bounds
    pointerNdc(e);
    const dist = camera.position.distanceTo(dragStartWorld);
    const halfH = Math.tan((camera.fov * Math.PI) / 360) * dist;
    const halfW = halfH * camera.aspect;
    camera.getWorldDirection(camF);
    const pitch = Math.max(0.3, Math.abs(camF.y));
    camR.set(1, 0, 0).applyQuaternion(camera.quaternion); camR.y = 0; camR.normalize();
    camU.set(0, 1, 0).applyQuaternion(camera.quaternion);
    camF.y = 0; camU.y = 0; camF.add(camU).normalize();
    _w.copy(dragStartWorld)
      .addScaledVector(camR, (dragNdc.x - dragStartNdc.x) * halfW)
      .addScaledVector(camF, (dragNdc.y - dragStartNdc.y) * (halfH / pitch));
    worldRoot.worldToLocal(_w);
    const lim = MARKER_LIMIT || objLimit();
    marker.position.x = Math.min(lim.maxX, Math.max(lim.minX, _w.x));
    marker.position.y = Math.min(lim.maxY, Math.max(lim.minY, _w.y));
    placeDelta.x = marker.position.x - PLACE0.x; placeDelta.y = marker.position.y - PLACE0.y;
    needsRender = true;
  });
  function endDrag() {
    if (!dragging) return;
    if (liveOn && dragTarget && dragTarget.name) {
      const g = objectMeshes[dragTarget.name];
      postLiveMove(dragTarget.name, g.position.x, g.position.y, g.position.z, true);
    }
    liveDraggedKey = null;
    dragging = false; dragTarget = null;
    controls.enabled = true;
    renderer.domElement.style.cursor = '';
    needsRender = true;
  }
  renderer.domElement.addEventListener('pointerup', function (e) {
    endDrag();
    if (!clickArmed) return;
    clickArmed = false;
    if (Math.hypot(e.clientX - clickX, e.clientY - clickY) > 5) return;
    const id = classifyClick(e);
    if (id && partClickCb) partClickCb(id);
  });
  renderer.domElement.addEventListener('pointercancel', function () { clickArmed = false; endDrag(); });

  function classifyClick(e) {
    pointerNdc(e);
    dragRay.setFromCamera(dragNdc, camera);
    let hits = dragRay.intersectObjects(draggableMeshes(), false);
    if (hits.length) {
      const o = hits[0].object;
      if (o.userData.simMarker) return 'place_area';
      return objectIdByKey[o.userData.simObj] || null;
    }
    if (robotModel) {
      hits = dragRay.intersectObject(robotModel.obj, true);
      for (let i = 0; i < hits.length; i++) {
        let o = hits[i].object;
        while (o && o !== scene3) {
          if (o.isURDFLink && o.name) {
            return linkToPart[String(o.name)] || (SCENE.robot && SCENE.robot.name) || null;
          }
          o = o.parent;
        }
      }
    }
    return null;
  }

  // glow entities in 3D — accepts object ids, mesh keys or segment step names
  function highlightObjects(ids) {
    const set = {};
    (ids || []).forEach(function (id) {
      id = String(id);
      set[id] = 1;
      if (SCENE && SCENE.segments) {
        const seg = SCENE.segments.find(function (s) { return s.step === id; });
        if (seg && seg.picks) set[seg.picks] = 1;
      }
    });
    for (const key in objectMeshes) {
      const on = !!set[key] || !!set[objectIdByKey[key]];
      objectMeshes[key].traverse(function (c) {
        if (c.isMesh && c.material && c.material.emissive) {
          c.material.emissive.setHex(on ? 0x39d5c8 : 0x000000);
          c.material.emissiveIntensity = on ? 0.55 : 0;
        }
      });
    }
    // direct link references: knowledge-base joint entities (l_shoulder_pan_joint → its
    // child link) and URDF-tree nodes ('urdf:<link>') resolve to link names
    const linkSet = {};
    (ids || []).forEach(function (id) {
      id = String(id);
      if (id.indexOf('urdf:') === 0) linkSet[id.slice(5)] = 1;
      const j = robotModel && robotModel.obj.joints && robotModel.obj.joints[id];
      if (j) {
        for (let i = 0; i < j.children.length; i++) {
          if (j.children[i].isURDFLink) { linkSet[j.children[i].name] = 1; break; }
        }
      }
    });
    // robot: glow meshes by part (scene.robot.parts, e.g. PR2LeftArm), by link,
    // or the whole robot when its own id is selected
    if (robotModel) {
      const robotName = SCENE && SCENE.robot && SCENE.robot.name;
      const wholeRobot = !!(robotName && set[robotName]);
      robotModel.obj.traverse(function (c) {
        if (!c.isMesh) return;
        const link = linkNameOf(c);
        const part = linkToPart[link];
        const on = wholeRobot || !!(part && set[part]) || !!linkSet[link];
        const mats = Array.isArray(c.material) ? c.material : [c.material];
        mats.forEach(function (m) {
          if (m && m.emissive) {
            m.emissive.setHex(on ? 0x39d5c8 : 0x000000);
            m.emissiveIntensity = on ? 0.45 : 0;
          }
        });
      });
    }
    // the place area: brighten the blue corner marker
    if (PLACE0) {
      const on = !!set['place_area'];
      marker.traverse(function (c) {
        if (!c.isMesh) return;
        c.material.color.setHex(on ? 0x8fdcff : 0x35a7ff);
        if (c.material.transparent) c.material.opacity = on ? 0.26 : 0.08;
      });
    }
    needsRender = true;
  }

  // %% live mode: attach to a running demo (cramera-live bridge, RViz-style)
  // The bridge streams the executing world's joints/base/objects in the exact
  // trajectory frame format; while attached, the viewer renders those instead
  // of the recording. The button appears whenever a bridge responds.
  const liveBtn = $('live-btn');
  const liveDot = $('live-indicator');   // red badge over the view
  // a recorded scene cannot be driven live, so the control says it switches views there
  if (liveBtn) {
    liveBtn.textContent = LiveMode.labelFor(SceneContext.name(), false);
    liveBtn.title = LiveMode.titleFor(SceneContext.name());
  }
  let liveOn = false, liveTimer = null, liveFails = 0, lastSeq = -1;
  // "always live": keep attaching whenever a demo is reachable, not just once per
  // page. Persisted, because live mode reloads the page whenever its bundle changes.
  const AUTO_LIVE_KEY = 'cramera-auto-live';
  function autoLiveOn() {
    try { return localStorage.getItem(AUTO_LIVE_KEY) !== '0'; } catch (e) { return true; }
  }
  function setAutoLive(on) {
    try { localStorage.setItem(AUTO_LIVE_KEY, on ? '1' : '0'); } catch (e) {}
  }
  let manualLiveDetach = false;  // the user clicked detach; holds off auto-live for this demo
  const liveCbs = [];                  // notified on attach/detach (graph tabs)
  let liveDraggedKey = null;           // object being dragged (poll must not fight it)
  let lastMovePost = 0;

  // viewer -> world: throttled while dragging, final=true on release
  function postLiveMove(key, x, y, z, final) {
    const now = performance.now();
    if (!final && now - lastMovePost < 100) return;
    lastMovePost = now;
    fetch(liveUrl() + '/move', {
      method: 'POST',
      body: JSON.stringify({ object: key, position: [round3(x), round3(y), round3(z)], final: !!final }),
    }).catch(function () {});
  }
  function round3(v) { return Math.round(v * 1000) / 1000; }

  function liveUrl() {
    const m = /[?&]live=([\w.:-]+)/.exec(window.location.search);
    return 'http://' + (m ? m[1] : (window.location.hostname + ':8765'));
  }
  function probeLive() {
    fetch(liveUrl() + '/info').then(function (r) { return r.json(); })
      .then(function (info) {
        if (liveBtn && !liveOn) liveBtn.style.display = info ? '' : 'none';
        // landing with no explicit ?scene=, or already on the live scene, attaches
        // the moment a bridge is reachable, instead of waiting for a manual click;
        // with auto-live on this keeps re-attaching (e.g. to the next demo run) —
        // unless the user detached this demo by hand
        if (info && LiveMode.shouldAutoAttach(
            SceneContext.name(), !noExplicitScene, liveOn, autoAttachedLive,
            autoLiveOn() && !manualLiveDetach)) {
          autoAttachedLive = true;
          goLiveOrAttach();
        }
        if (info) reloadIfBundleIsStale(info);
      })
      .catch(function () {
        manualLiveDetach = false;    // the demo went away; the next one attaches again
        if (liveBtn && !liveOn) liveBtn.style.display = 'none';
      });
  }
  // this page's bundle no longer describes the running demo — a model was parsed
  // after the bundle was built, or the bundle predates the world attach and so knows
  // neither the models' prefixes nor the robot (see LiveMode.needsLiveSceneReload):
  // rebundle the live scene, then reload onto it
  let liveReloadRequested = false;
  // attaching means "show the running demo": the toggle path never touches
  // /live_scene, so a page already sitting on the live scene would otherwise keep a
  // bundle from a previous run (or one built before the world attached) forever.
  // Rebuild the bundle against the demo's current world and reload if this page was
  // built from a different one.
  function verifyLiveBundle() {
    if (liveReloadRequested || !LiveMode.isLiveScene(SceneContext.name())) return;
    fetch(liveUrl() + '/live_scene').then(function (r) { return r.ok ? r.json() : null; })
      .then(function (d) {
        if (!d || !d.scene) return;
        return fetch(SCENES + d.scene + '/scene.json', { cache: 'no-store' })
          .then(function (r) { return r.ok ? r.json() : null; })
          .then(function (fresh) {
            if (!LiveMode.sameBundle(SCENE, fresh)) {
              liveReloadRequested = true;
              window.location.reload();
            }
          });
      })
      .catch(function () {});
  }
  function reloadIfBundleIsStale(info) {
    if (liveReloadRequested
        || !LiveMode.needsLiveSceneReload(SceneContext.name(), liveOn, SCENE, info)) return;
    liveReloadRequested = true;
    fetch(liveUrl() + '/live_scene').then(function (r) {
      if (r.ok) window.location.reload();
      else liveReloadRequested = false;        // bundling failed — try again next probe
    }).catch(function () { liveReloadRequested = false; });
  }
  // %% the CRAM debug-marker overlay
  let lastMarkersVersion = -1;
  let lastMarkerPayload = null;         // for re-filtering without a refetch
  let hiddenMarkerNs = MarkerSettings.hiddenNamespaces(window.localStorage);
  function refreshMarkers() {
    fetch(liveUrl() + '/markers').then(function (r) { return r.json(); })
      .then(function (payload) {
        lastMarkerPayload = payload;
        rebuildMarkers();
        renderMarkerNamespaces();
      }).catch(function () {});
  }
  function rebuildMarkers() {
    clearMarkers();
    const markers = lastMarkerPayload ? lastMarkerPayload.markers : [];
    MarkerSettings.visibleMarkers(markers, hiddenMarkerNs).forEach(function (marker) {
      const built = buildMarker(marker);
      if (built) markerRoot.add(built);
    });
    needsRender = true;
  }
  function clearMarkers() {
    while (markerRoot.children.length) {
      const child = markerRoot.children[0];
      markerRoot.remove(child);
      child.traverse(function (c) {
        if (c.geometry) c.geometry.dispose();
        if (c.material) { c.material.map && c.material.map.dispose(); c.material.dispose(); }
      });
    }
  }
  function markerMaterial(spec) {
    return new THREE.MeshStandardMaterial({
      color: new THREE.Color(spec.color),
      transparent: spec.opacity < 1, opacity: spec.opacity,
      roughness: 0.55, metalness: 0.05, envMapIntensity: 0.6,
    });
  }
  function buildMarker(marker) {
    const spec = MarkerSpecs.buildSpec(marker);
    if (!spec) return null;
    const holder = new THREE.Group();
    holder.position.set(spec.pose[0], spec.pose[1], spec.pose[2]);
    holder.quaternion.set(spec.pose[3], spec.pose[4], spec.pose[5], spec.pose[6]);
    if (spec.type === 'box') {
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), markerMaterial(spec));
      mesh.scale.set(spec.size[0], spec.size[1], spec.size[2]);
      holder.add(mesh);
    } else if (spec.type === 'sphere') {
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.5, 20, 14), markerMaterial(spec));
      mesh.scale.set(spec.size[0], spec.size[1], spec.size[2]);
      holder.add(mesh);
    } else if (spec.type === 'cylinder') {
      const geometry = new THREE.CylinderGeometry(0.5, 0.5, 1, 24);
      geometry.rotateX(Math.PI / 2);                      // marker cylinders run along Z
      const mesh = new THREE.Mesh(geometry, markerMaterial(spec));
      mesh.scale.set(spec.size[0], spec.size[1], spec.size[2]);
      holder.add(mesh);
    } else if (spec.type === 'arrow') {
      const material = markerMaterial(spec);
      const headLength = Math.min(spec.length * 0.3, spec.headDiameter * 1.5);
      const shaft = new THREE.Mesh(
        new THREE.CylinderGeometry(spec.shaftDiameter / 2, spec.shaftDiameter / 2, spec.length - headLength, 12),
        material);
      shaft.rotation.z = -Math.PI / 2;                    // along +X
      shaft.position.x = (spec.length - headLength) / 2;
      const head = new THREE.Mesh(
        new THREE.ConeGeometry(spec.headDiameter / 2, headLength, 12), material);
      head.rotation.z = -Math.PI / 2;
      head.position.x = spec.length - headLength / 2;
      holder.add(shaft); holder.add(head);
    } else if (spec.type === 'line' || spec.type === 'segments') {
      const geometry = new THREE.BufferGeometry().setFromPoints(
        spec.points.map(function (p) { return new THREE.Vector3(p[0], p[1], p[2]); }));
      const material = new THREE.LineBasicMaterial({
        color: new THREE.Color(spec.color), transparent: spec.opacity < 1, opacity: spec.opacity });
      holder.add(spec.type === 'line' ? new THREE.Line(geometry, material)
        : new THREE.LineSegments(geometry, material));
    } else if (spec.type === 'points') {
      const geometry = new THREE.BufferGeometry().setFromPoints(
        spec.points.map(function (p) { return new THREE.Vector3(p[0], p[1], p[2]); }));
      holder.add(new THREE.Points(geometry, new THREE.PointsMaterial({
        color: new THREE.Color(spec.color), size: spec.size, sizeAttenuation: true,
        transparent: spec.opacity < 1, opacity: spec.opacity })));
    } else if (spec.type === 'text') {
      const label = makeLabel(spec.text, spec.color);
      label.visible = true;
      holder.add(label);
    }
    return holder;
  }

  // %% frame axes (the in-scene TF display)
  // A triad is a child of the frame's own object, so it moves with the world for
  // free — playback drives the URDF joints, live mode drives the same objects.
  // The arms ignore depth, since most link frames sit inside their own mesh and
  // would otherwise never be visible.
  const frameDisplay = {
    visible: false, names: false, size: FrameAxes.DEFAULT_SIZE,
    hidden: { sources: {}, frames: {} },
  };
  const frameTriads = [];

  function applyFrameTriadSize(triad) {
    triad.arms.scale.setScalar(frameDisplay.size);
    triad.label.position.set(0, 0, frameDisplay.size * 1.25);
  }

  function buildFrameTriad(frame) {
    const group = new THREE.Group();
    const arms = new THREE.AxesHelper(1);
    arms.material.depthTest = false;
    arms.material.transparent = true;
    arms.renderOrder = 3;
    const label = makeLabel(frame.name, FrameAxes.AXES[0].color);
    label.visible = frameDisplay.names;
    group.add(arms);
    group.add(label);
    frame.object.add(group);
    return { id: frame.id, group: group, arms: arms, label: label };
  }

  function disposeFrameTriad(triad) {
    triad.group.parent && triad.group.parent.remove(triad.group);
    triad.arms.geometry.dispose();
    triad.arms.material.dispose();
    triad.label.material.map && triad.label.material.map.dispose();
    triad.label.material.dispose();
  }

  // Add a triad to every frame that has none and drop the ones whose frame is gone,
  // so a live spawn or a scene switch is picked up without rebuilding the rest.
  function refreshFrameAxes() {
    const frames = frameDisplay.visible
      ? FrameAxes.visibleFrames(FrameAxes.framesOf(models, objectMeshes), frameDisplay.hidden)
      : [];
    const wanted = {};
    frames.forEach(function (frame) { wanted[frame.id] = frame; });
    for (let i = frameTriads.length - 1; i >= 0; i--) {
      if (wanted[frameTriads[i].id]) continue;
      disposeFrameTriad(frameTriads[i]);
      frameTriads.splice(i, 1);
    }
    const present = {};
    frameTriads.forEach(function (triad) { present[triad.id] = true; });
    frames.forEach(function (frame) {
      if (present[frame.id]) return;
      const triad = buildFrameTriad(frame);
      applyFrameTriadSize(triad);
      frameTriads.push(triad);
    });
    needsRender = true;
  }

  function applyLive(st) {
    if (!st || !st.frames) return;
    for (const k in st.frames) {
      const j = JointRouting.jointFor(models, k);
      if (j) j.setJointValue(st.frames[k]);
    }
    if (robotModel && st.base) setPose(robotModel.obj, st.base, st.base, 0);
    // every bundled model root the bridge streams: a second robot drives, a moved
    // environment model follows (the primary robot's entry re-applies st.base)
    const modelBases = st.modelBases || {};
    for (const prefix in modelBases) {
      models.forEach(function (m) {
        if (m.prefix === prefix) setPose(m.obj, modelBases[prefix], modelBases[prefix], 0);
      });
    }
    if (typeof st.markersVersion === 'number' && st.markersVersion !== lastMarkersVersion) {
      lastMarkersVersion = st.markersVersion;
      refreshMarkers();
    }
    let unknown = false;
    liveStateKeys = st.objects || {};
    for (const key in liveStateKeys) {
      if (key === liveDraggedKey) continue;    // the mouse owns this one right now
      const g = objectMeshes[key];
      if (g) {
        // the running world HAS this object, so it belongs on screen, even if an
        // earlier catalog answer hid it.
        if (!g.visible) { g.visible = true; needsRender = true; }
        setPose(g, liveStateKeys[key], liveStateKeys[key], 0);
      } else unknown = true;                   // an object the demo spawned mid-run
    }
    if (unknown) syncLiveObjects();            // fetch the catalog & spawn the newcomers
    if (follow && robotCenter(_target)) controls.target.lerp(_target, 0.08);
    needsRender = true;
  }
  let livePolls = 0;
  function livePoll() {
    if (++livePolls % 45 === 0) syncLiveObjects();   // ~3 s catalog reconcile
    fetch(liveUrl() + '/state').then(function (r) { return r.json(); })
      .then(function (st) {
        liveFails = 0;
        if (st.sequenceNumber !== lastSeq) { lastSeq = st.sequenceNumber; applyLive(st); }
      })
      .catch(function () { if (++liveFails > 30) setLive(false); });
  }
  // sync the scene's objects to the ones that actually exist in the running
  // world: spawn any the viewer is missing (geometry served by the bridge),
  // hide bundle objects the demo doesn't have. Runs once per attach.
  let liveSyncing = false;
  let liveStateKeys = {};        // objects present in the newest /state payload
  function syncLiveObjects() {
    if (!liveOn || liveSyncing) return;
    liveSyncing = true;
    fetch(liveUrl() + '/objects').then(function (r) { return r.json(); })
      .then(function (d) {
        const live = d.objects || [];
        const liveKeys = {};
        live.forEach(function (o) {
          liveKeys[o.key] = 1;
          if (objectMeshes[o.key]) {                  // already present — reuse
            objectMeshes[o.key].visible = true;
            return;
          }
          const spec = { id: o.id, key: o.key, color: o.color };
          if (o.kind === 'shapes' && o.shapes) { spec.shapes = o.shapes; spec.liveBase = liveUrl(); }
          else if (o.kind === 'mesh' && o.mesh) { spec.meshUrl = liveUrl() + o.mesh; spec.format = o.format; }
          else spec.box = o.size || [0.06, 0.06, 0.1];
          liveSpawned[o.key] = true;
          addObject(spec);
        });
        // Hide (don't delete) bundle objects the live world doesn't have — but
        // only once the bridge actually reports objects. An empty catalog means
        // "the demo hasn't spawned them yet" (or the world was mid-modification
        // when the bridge last bound), not "this world has no objects"; hiding
        // on that answer blanks the scene for the rest of the session.
        if (live.length || Object.keys(liveStateKeys).length) {
          for (const key in objectMeshes) {
            if (!liveKeys[key] && !(key in liveStateKeys)) objectMeshes[key].visible = false;
          }
        }
        needsRender = true;
      }).catch(function () {})
      .then(function () { liveSyncing = false; });
  }

  // watching a running demo "live" always means being on the reserved live scene,
  // which the bridge bundles fresh from the demo's *current* world on every attach
  // (see cramera.live.live_bundle) — this just gets the browser there, or, once
  // already there, toggles the plain pose overlay below exactly like any scene.
  var LIVE_SCENE_RETRY_MS = 1000;
  function goLiveOrAttach() {
    if (LiveMode.actionFor(SceneContext.name()) === LiveMode.TOGGLE) {
      // detaching by hand must stick even with auto-live on — until this demo goes
      // away, after which the next run is fair game again
      manualLiveDetach = liveOn;
      setLive(!liveOn);
      return;
    }
    fetch(liveUrl() + '/live_scene').then(function (r) { return r.json(); })
      .then(function (d) {
        if (d && d.scene) {
          const params = new URLSearchParams(window.location.search);
          params.set('scene', d.scene);
          window.location.search = params.toString();
        } else {
          // the bridge is up (the button is visible at all) but the demo hasn't
          // parsed its world yet — keep checking until it has
          setTimeout(goLiveOrAttach, LIVE_SCENE_RETRY_MS);
        }
      }).catch(function () {});
  }

  function setLive(on) {
    // A recorded scene and the running demo are separate worlds; the stream replacing a
    // recording's object poses would silently overwrite whatever was arranged here, so it
    // only ever drives the live scene. Reaching this from anywhere else is a wiring
    // mistake, not a user action — goLiveOrAttach navigates instead.
    const sceneName = SceneContext.name();
    if (on && !LiveMode.attachable(sceneName)) {
      console.error('[robot-scene] refusing to attach the live stream to "%s" — '
        + 'only "%s" can be driven live', sceneName, LiveMode.SCENE_NAME);
      return;
    }
    liveOn = on;
    liveCbs.forEach(function (cb) { try { cb(on); } catch (e) {} });
    if (liveDot) liveDot.classList.toggle('on', on);
    if (liveBtn) {
      liveBtn.classList.toggle('on', on);
      liveBtn.textContent = LiveMode.labelFor(sceneName, on);
      liveBtn.title = LiveMode.titleFor(sceneName);
    }
    // the live pose stream and trajectory playback both drive the same joints/poses;
    // playing a recording while live would just get overwritten every tick, so the
    // playback controls are disabled for as long as the stream is attached
    if (playBtn) playBtn.disabled = on;
    if (scrubber) scrubber.disabled = on;
    if (speedSelect) speedSelect.disabled = on;
    if (on) {
      playing = false;
      lastSeq = -1;
      lastMarkersVersion = -1;
      liveStateKeys = {};
      livePolls = 0;
      applyMarkerTopicOverrides();
      verifyLiveBundle();
      syncLiveObjects();
      liveTimer = setInterval(livePoll, 66);          // ~15 Hz render updates
    } else if (liveTimer) {
      clearInterval(liveTimer);
      liveTimer = null;
      // remove objects that only existed for the live world, restore the rest
      clearMarkers();
      for (const key in liveSpawned) removeObject(key);
      for (const key in objectMeshes) objectMeshes[key].visible = true;
      if (traj) applyFrame(playhead);                 // back to the recording
    }
    needsRender = true;
  }
  if (liveBtn) liveBtn.addEventListener('click', goLiveOrAttach);
  const probeTimer = setInterval(probeLive, LIVE_PROBE_INTERVAL_MS);
  probeLive();

  // %% SSAO
  let composer = null, ssaoPass = null;
  (function setupSSAO() {
    if (!(THREE.EffectComposer && THREE.RenderPass && THREE.SSAOPass && THREE.ShaderPass && THREE.CopyShader)) return;
    try {
      const w = container.clientWidth || 800, h = container.clientHeight || 600;
      composer = new THREE.EffectComposer(renderer);
      composer.addPass(new THREE.RenderPass(scene3, camera));
      ssaoPass = new THREE.SSAOPass(scene3, camera, w, h);
      ssaoPass.kernelRadius = 0.12;
      ssaoPass.minDistance = 0.001;
      ssaoPass.maxDistance = 0.04;
      composer.addPass(ssaoPass);
      const copy = new THREE.ShaderPass(THREE.CopyShader);
      copy.renderToScreen = true;
      composer.addPass(copy);
    } catch (e) { composer = null; }
  })();
  function renderFrame() {
    if (composer) composer.render();
    else renderer.render(scene3, camera);
  }

  // %% render loop
  const clock = new THREE.Clock();
  let running = true;
  function tick() {
    if (!running) return;
    requestAnimationFrame(tick);
    // imported models finish loading asynchronously, so their materials are re-tamed
    // for a while after mount; once that window closes the loop goes on-demand again
    if (models.length && clock.getElapsedTime() < MATERIAL_SETTLE_SECONDS) {
      upgradeMaterials();
      needsRender = true;
    }
    const moved = controls.update();
    if (playing && traj && !liveOn) {
      playhead += ((traj.framesPerSecond || 30) / 60) * 1.6 * playbackSpeedMultiplier;
      if (playhead >= traj.frames.length - 1) { playhead = traj.frames.length - 1; playing = false; stepCb('__done__'); }
      applyFrame(playhead);
      playheadCbs.forEach(function (cb) { cb(playhead); });
      if (follow && robotCenter(_target)) controls.target.lerp(_target, 0.06);
      needsRender = true;
    }
    if (!needsRender && !moved && !controls.autoRotate) return;
    renderFrame();
    needsRender = false;
  }
  tick();

  function resize() {
    const w = container.clientWidth, h = container.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false);
    if (composer) composer.setSize(w, h);
    if (ssaoPass) ssaoPass.setSize(w, h);
    camera.aspect = w / h; camera.updateProjectionMatrix();
    needsRender = true;
  }
  window.addEventListener('resize', resize);
  const containerObserver = new ResizeObserver(resize);
  containerObserver.observe(container);
  resize();

  window.RobotView = {
    onReady: function (cb) { if (finalized && traj) cb(); else readyCbs.push(cb); },
    hasTrajectory: function () { return !!traj; },
    playTrajectory: playTrajectory,
    stopTrajectory: stopTrajectory,
    isPlayingTrajectory: function () { return playing; },
    setPlaybackSpeed: function (multiplier) {
      playbackSpeedMultiplier = RecordingMode.clampSpeed(multiplier);
    },
    seek: seekTo,
    getPlayhead: function () { return playhead; },
    frameCount: function () { return traj ? traj.frames.length : 0; },
    framesPerSecond: function () { return (traj && traj.framesPerSecond) || 30; },
    onPlayheadChange: function (cb) { playheadCbs.push(cb); },
    onStepStart: function (cb) { stepCb = cb; },
    setAutoRotate: function (on) { controls.autoRotate = on; controls.autoRotateSpeed = 0.5; needsRender = true; },
    setFloorVisible: function (on) { ground.visible = on; needsRender = true; },
    setFollow: function (on) { follow = on; },
    setPropsVisible: function (on) {
      for (const n in objectMeshes) objectMeshes[n].visible = on;
      marker.visible = on && !!PLACE0;
      needsRender = true;
    },
    highlightObjects: highlightObjects,
    onPartClick: function (cb) { partClickCb = cb; },
    getScene: function () { return SCENE; },
    // live bridge, shared with the graph panel (plan / statechart tabs)
    isLive: function () { return liveOn; },
    liveUrl: liveUrl,
    onLiveChange: function (cb) { liveCbs.push(cb); },
    setLabelsAlways: function (on) {
      labelsOn = !!on;
      for (const k in objectLabels) objectLabels[k].visible = labelsOn;
      needsRender = true;
    },
    setFramesVisible: function (on) {
      frameDisplay.visible = !!on;
      refreshFrameAxes();
    },
    setFrameNamesVisible: function (on) {
      frameDisplay.names = !!on;
      frameTriads.forEach(function (triad) { triad.label.visible = frameDisplay.names; });
      needsRender = true;
    },
    setFrameAxisSize: function (size) {
      frameDisplay.size = FrameAxes.clampSize(size);
      frameTriads.forEach(applyFrameTriadSize);
      needsRender = true;
    },
    setHiddenFrames: function (hidden) {
      frameDisplay.hidden = hidden || { sources: {}, frames: {} };
      refreshFrameAxes();
    },
    frameSources: function () { return FrameAxes.sourcesOf(models, objectMeshes); },
    frames: function () { return FrameAxes.framesOf(models, objectMeshes); },
    frameCountOnScreen: function () { return frameTriads.length; },
    thumbnailAt: thumbnailAt,
  };

  // %% panel wiring
  // Everything below couples the viewer to the page: buttons, overlays and the
  // event bus. The 3D code above knows nothing about other panels.
  const RobotView = window.RobotView;

  // %% bus: outbound
  RobotView.onPartClick(function (id) { bus.emit('scene:part-clicked', { id: id }); });
  RobotView.onLiveChange(function (on) { bus.emit('live:changed', { on: on, url: liveUrl() }); });

  // %% bus: inbound
  bus.on('entity:highlight', function (p) { highlightObjects((p && p.ids) || []); });

  // %% play button
  const playBtn = $('play-btn');
  playBtn.addEventListener('click', function () {
    if (!RobotView.hasTrajectory()) return;
    if (RobotView.isPlayingTrajectory()) {
      RobotView.stopTrajectory();
      playBtn.classList.remove('playing'); playBtn.textContent = '▶ Play robot motion';
    } else {
      RobotView.playTrajectory();
      playBtn.classList.add('playing'); playBtn.textContent = '⏸ Stop';
    }
  });
  RobotView.onStepStart(function (step) {
    if (step === '__done__') {
      playBtn.classList.remove('playing'); playBtn.textContent = '▶ Play robot motion';
      highlightObjects([]);
    }
    bus.emit('scene:step', { step: step });
  });

  // %% playback speed
  const speedSelect = $('playback-speed');
  RecordingMode.SPEED_OPTIONS.forEach(function (speed) {
    const option = document.createElement('option');
    option.value = String(speed);
    option.textContent = speed + '×';
    if (speed === 1) option.selected = true;
    speedSelect.appendChild(option);
  });
  speedSelect.addEventListener('change', function () {
    RobotView.setPlaybackSpeed(parseFloat(speedSelect.value));
  });
  RobotView.onReady(function () {
    speedSelect.style.display = RobotView.hasTrajectory() ? '' : 'none';
  });

  // %% playback scrubber
  const scrubRow = $('playback-scrub-row');
  const scrubber = $('playback-scrubber');
  const timeLabel = $('playback-time');
  let scrubbing = false, wasPlayingBeforeScrub = false;

  function formatTime(frame, fps) {
    const totalSeconds = Math.max(0, frame) / fps;
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = Math.floor(totalSeconds % 60);
    return minutes + ':' + (seconds < 10 ? '0' : '') + seconds;
  }
  function updateScrubberUI(frame) {
    if (!scrubbing) scrubber.value = String(Math.round(frame));
    const fps = RobotView.framesPerSecond();
    timeLabel.textContent = formatTime(frame, fps) + ' / ' + formatTime(RobotView.frameCount() - 1, fps);
  }
  RobotView.onReady(function () {
    const visible = RobotView.hasTrajectory();
    scrubRow.style.display = visible ? '' : 'none';
    if (visible) {
      scrubber.max = String(Math.max(0, RobotView.frameCount() - 1));
      updateScrubberUI(RobotView.getPlayhead());
      renderTimelineEvents();
    }
  });

  // %% key events on the timeline
  // Each recorded step, pick and release gets a mark on the scrubber: hovering one
  // previews what the scene looks like there, clicking one jumps to it.
  const timelineEventsEl = $('timeline-events');
  const timelinePreviewEl = $('timeline-preview');

  function renderTimelineEvents() {
    timelineEventsEl.innerHTML = '';
    const frameCount = RobotView.frameCount();
    TimelineEvents.of(RobotView.getScene()).forEach(function (event) {
      const mark = document.createElement('button');
      mark.className = 'timeline-mark';
      mark.style.left = TimelineEvents.positionOf(event.frame, frameCount) + '%';
      mark.style.background = TimelineEvents.colorOf(event);
      mark.title = TimelineEvents.describe(event);
      mark.addEventListener('mouseenter', function () { showTimelinePreview(event, mark); });
      mark.addEventListener('mouseleave', hideTimelinePreview);
      mark.addEventListener('click', function (clicked) {
        clicked.preventDefault();
        RobotView.seek(event.frame);
        updateScrubberUI(event.frame);
      });
      timelineEventsEl.appendChild(mark);
    });
  }

  // The thumbnail costs a render, so the card goes up with its caption first and the
  // image lands on the next frame — a pointer sweeping along the timeline never
  // stalls on a mark it is only passing over.
  function showTimelinePreview(event, mark) {
    timelinePreviewEl.classList.remove('hidden');
    timelinePreviewEl.style.left = TimelineEvents.previewOffset(
      parseFloat(mark.style.left),
      timelineEventsEl.clientWidth,
      timelinePreviewEl.offsetWidth) + 'px';
    timelinePreviewEl.innerHTML = '';
    const image = document.createElement('div');
    image.className = 'tp-loading';
    image.textContent = 'rendering…';
    const label = document.createElement('div');
    label.className = 'tp-label';
    label.textContent = TimelineEvents.describe(event);
    const time = document.createElement('div');
    time.className = 'tp-time';
    time.textContent = TimelineEvents.timeOf(event.frame, RobotView.framesPerSecond());
    timelinePreviewEl.appendChild(image);
    timelinePreviewEl.appendChild(label);
    timelinePreviewEl.appendChild(time);
    requestAnimationFrame(function () {
      if (timelinePreviewEl.classList.contains('hidden')) return;
      const source = RobotView.thumbnailAt(event.frame);
      if (!source || !image.parentNode) return;
      const rendered = document.createElement('img');
      rendered.src = source;
      rendered.alt = TimelineEvents.describe(event);
      timelinePreviewEl.replaceChild(rendered, image);
    });
  }

  function hideTimelinePreview() {
    timelinePreviewEl.classList.add('hidden');
  }
  RobotView.onPlayheadChange(updateScrubberUI);
  scrubber.addEventListener('pointerdown', function () {
    scrubbing = true;
    wasPlayingBeforeScrub = RobotView.isPlayingTrajectory();
    if (wasPlayingBeforeScrub) {
      RobotView.stopTrajectory();
      playBtn.classList.remove('playing'); playBtn.textContent = '▶ Play robot motion';
    }
  });
  scrubber.addEventListener('input', function () {
    const frame = parseInt(scrubber.value, 10);
    RobotView.seek(frame);
    updateScrubberUI(frame);
  });
  scrubber.addEventListener('pointerup', function () {
    scrubbing = false;
    if (wasPlayingBeforeScrub) {
      RobotView.playTrajectory();
      playBtn.classList.add('playing'); playBtn.textContent = '⏸ Stop';
    }
  });

  // %% recording controls (capturing a live run into a temporary, replayable scene)
  const recordStopBtn = $('record-stop-btn');
  const recordDiscardBtn = $('record-discard-btn');
  const recordSaveBtn = $('record-save-btn');
  let recordingState = RecordingMode.STATE.IDLE;

  function updateRecordingButtons() {
    const visible = RecordingMode.controlsVisible({ state: recordingState });
    recordStopBtn.style.display = visible ? '' : 'none';
    recordDiscardBtn.style.display = visible ? '' : 'none';
    recordSaveBtn.style.display = visible ? '' : 'none';
    recordStopBtn.textContent = RecordingMode.stopButtonLabel(recordingState);
    recordStopBtn.disabled = !RecordingMode.canStop(recordingState);
    recordSaveBtn.disabled = !RecordingMode.canSave(recordingState);
  }

  // The bridge (the demo process, liveUrl()) is the source of truth while it is
  // reachable -- only it knows whether capture is still running. Once a run is
  // finalized (or the demo process has since exited entirely -- the recording was
  // already written to disk either by an explicit stop or by its exit-time safety
  // net, see cramera.live.visualization), discarding/saving it is a pure filesystem
  // action the always-on server (this same origin) can do without the bridge at all.
  // Every recording action below tries the bridge first and falls back to the
  // general server's /api/recording/* the moment that fetch fails to connect.
  function postRecordingAction(bridgePath, fallbackPath, body) {
    const options = { method: 'POST' };
    if (body) options.body = JSON.stringify(body);
    return fetch(liveUrl() + bridgePath, options)
      .then(function (r) { return r.json(); })
      .catch(function () {
        return fetch(fallbackPath, options).then(function (r) { return r.json(); });
      });
  }

  function pollRecordingStatus() {
    fetch(liveUrl() + '/recording').then(function (r) { return r.json(); })
      .then(function (status) {
        recordingState = (status && status.state) || RecordingMode.STATE.IDLE;
        updateRecordingButtons();
      })
      .catch(function () {
        fetch('/api/recording/status').then(function (r) { return r.json(); })
          .then(function (status) {
            recordingState = (status && status.state) || RecordingMode.STATE.IDLE;
            updateRecordingButtons();
          })
          .catch(function () {});
      });
  }
  updateRecordingButtons();
  const recordingProbeTimer = setInterval(pollRecordingStatus, LIVE_PROBE_INTERVAL_MS);
  pollRecordingStatus();

  recordStopBtn.addEventListener('click', function () {
    fetch(liveUrl() + '/recording/stop', { method: 'POST' }).then(function (r) { return r.json(); })
      .then(function (d) {
        pollRecordingStatus();
        if (!d || !d.ok) return;
        const params = new URLSearchParams(window.location.search);
        params.set('scene', d.scene);
        window.location.search = params.toString();
      })
      .catch(function () {});
  });

  recordDiscardBtn.addEventListener('click', function () {
    postRecordingAction('/recording/discard', '/api/recording/discard').then(function () {
      pollRecordingStatus();
      if (RecordingMode.isRecordingScene(SceneContext.name())) {
        const params = new URLSearchParams(window.location.search);
        params.delete('scene');
        window.location.search = params.toString();
      }
    });
  });

  recordSaveBtn.addEventListener('click', function () {
    const name = window.prompt('Save this recording as:');
    if (name === null) return;
    if (!RecordingMode.isValidSaveName(name)) {
      window.alert('Scene names must be 1-64 characters of letters, digits, "_" or "-".');
      return;
    }
    postRecordingAction('/recording/save', '/api/recording/save', { name: name })
      .then(function (d) {
        if (!d || !d.ok) {
          window.alert('Could not save the recording: ' + ((d && d.error) || 'unknown error'));
          return;
        }
        pollRecordingStatus();
        const params = new URLSearchParams(window.location.search);
        params.set('scene', d.scene);
        window.location.search = params.toString();
      });
  });

  // %% layers panel
  function bindLayer(id, method) {
    const el = $(id);
    el.addEventListener('change', function () { RobotView[method](el.checked); });
  }
  bindLayer('lyr-objects', 'setPropsVisible');
  const markersLayerEl = $('lyr-markers');
  markersLayerEl.addEventListener('change', function () {
    markerRoot.visible = markersLayerEl.checked;
    needsRender = true;
  });

  // %% marker settings (topics like RViz displays, namespaces like its checkboxes)
  const markerSettingsEl = $('marker-settings');
  const markerGearEl = $('marker-gear');
  markerGearEl.addEventListener('click', function (event) {
    event.preventDefault();
    markerSettingsEl.classList.toggle('hidden');
    if (!markerSettingsEl.classList.contains('hidden')) renderMarkerSettings();
  });

  function renderMarkerSettings() {
    fetch(liveUrl() + '/marker_topics').then(function (r) { return r.json(); })
      .then(function (settings) {
        markerSettingsEl.innerHTML = '';
        if (!settings.ros) {
          markerSettingsEl.innerHTML = '<div class="ms-note">no ROS in the demo process</div>';
          renderMarkerNamespaces();
          return;
        }
        const title = document.createElement('div');
        title.className = 'ms-title';
        title.textContent = 'topics';
        markerSettingsEl.appendChild(title);
        (settings.available || []).forEach(function (topic) {
          const row = document.createElement('label');
          row.className = 'lp-row ms-row';
          const box = document.createElement('input');
          box.type = 'checkbox';
          box.checked = settings.subscribed.indexOf(topic) !== -1;
          box.addEventListener('change', function () {
            MarkerSettings.setTopicOverride(window.localStorage, topic, box.checked);
            fetch(liveUrl() + '/marker_topics', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ topic: topic, subscribed: box.checked }),
            }).then(function () { renderMarkerSettings(); }).catch(function () {});
          });
          row.appendChild(box);
          row.appendChild(document.createTextNode(topic));
          markerSettingsEl.appendChild(row);
        });
        const nsHolder = document.createElement('div');
        nsHolder.id = 'marker-namespaces';
        markerSettingsEl.appendChild(nsHolder);
        renderMarkerNamespaces();
      }).catch(function () {});
  }

  function renderMarkerNamespaces() {
    const holder = markerSettingsEl.querySelector('#marker-namespaces');
    if (!holder) return;
    holder.innerHTML = '';
    const namespaces = MarkerSettings.namespacesOf(lastMarkerPayload ? lastMarkerPayload.markers : []);
    if (!namespaces.length) return;
    const title = document.createElement('div');
    title.className = 'ms-title';
    title.textContent = 'namespaces';
    holder.appendChild(title);
    namespaces.forEach(function (ns) {
      const row = document.createElement('label');
      row.className = 'lp-row ms-row';
      const box = document.createElement('input');
      box.type = 'checkbox';
      box.checked = !hiddenMarkerNs[ns];
      box.addEventListener('change', function () {
        hiddenMarkerNs = MarkerSettings.setNamespaceHidden(window.localStorage, ns, !box.checked);
        rebuildMarkers();
      });
      row.appendChild(box);
      row.appendChild(document.createTextNode(ns));
      holder.appendChild(row);
    });
  }

  // the demo process starts from its default topics; re-apply the user's choices
  function applyMarkerTopicOverrides() {
    const overrides = MarkerSettings.topicOverrides(window.localStorage);
    Object.keys(overrides).forEach(function (topic) {
      fetch(liveUrl() + '/marker_topics', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ topic: topic, subscribed: overrides[topic] }),
      }).catch(function () {});
    });
  }
  // %% frame display (axis size and names, remembered like the marker settings)
  const framesLayerEl = $('lyr-frames');
  const frameSettingsEl = $('frame-settings');
  const frameGearEl = $('frame-gear');

  function applyFrameSettings(stored) {
    framesLayerEl.checked = stored.visible;
    RobotView.setFrameAxisSize(stored.size);
    RobotView.setFrameNamesVisible(stored.names);
    RobotView.setHiddenFrames(FrameAxes.hidden(window.localStorage));
    RobotView.setFramesVisible(stored.visible);
  }

  function renderFrameSettings(stored) {
    frameSettingsEl.innerHTML = '';
    const sizeRow = document.createElement('label');
    sizeRow.className = 'ms-slider';
    sizeRow.appendChild(document.createTextNode('size'));
    const slider = document.createElement('input');
    slider.type = 'range';
    slider.min = String(FrameAxes.MIN_SIZE);
    slider.max = String(FrameAxes.MAX_SIZE);
    slider.step = '0.01';
    slider.value = String(stored.size);
    const readout = document.createElement('span');
    readout.textContent = stored.size.toFixed(2) + ' m';
    slider.addEventListener('input', function () {
      const updated = FrameAxes.setSize(window.localStorage, slider.value);
      readout.textContent = updated.size.toFixed(2) + ' m';
      RobotView.setFrameAxisSize(updated.size);
    });
    sizeRow.appendChild(slider);
    sizeRow.appendChild(readout);
    frameSettingsEl.appendChild(sizeRow);

    const namesRow = document.createElement('label');
    namesRow.className = 'lp-row ms-row';
    const namesBox = document.createElement('input');
    namesBox.type = 'checkbox';
    namesBox.checked = stored.names;
    namesBox.addEventListener('change', function () {
      RobotView.setFrameNamesVisible(
        FrameAxes.setNames(window.localStorage, namesBox.checked).names);
    });
    namesRow.appendChild(namesBox);
    namesRow.appendChild(document.createTextNode('frame names'));
    frameSettingsEl.appendChild(namesRow);
    renderFrameSources();
    refreshFrameTicks();
  }

  // A source (a loaded model, or the loose objects) opens into its own frames: a
  // whole robot is a hundred of them, so the list starts collapsed and the source
  // row ticks them all at once, while the level below ticks one frame at a time.
  const expandedFrameSources = {};
  const frameSourceDisclosures = {};
  const frameSourceBoxes = {};
  const frameBoxes = {};

  function renderFrameSources() {
    const sources = RobotView.frameSources();
    if (!sources.length) return;
    Object.keys(frameSourceBoxes).forEach(function (source) {
      delete frameSourceBoxes[source]; delete frameSourceDisclosures[source];
      delete frameBoxes[source];
    });
    const title = document.createElement('div');
    title.className = 'ms-title';
    title.textContent = 'frames of';
    frameSettingsEl.appendChild(title);
    sources.forEach(function (source) {
      frameSettingsEl.appendChild(frameSourceRow(source));
      const nested = document.createElement('div');
      nested.className = 'ms-nested';
      nested.style.display = expandedFrameSources[source] ? '' : 'none';
      frameSourceRows(source).forEach(function (row) { nested.appendChild(row); });
      frameSettingsEl.appendChild(nested);
      frameSourceDisclosures[source].addEventListener('click', function (event) {
        event.preventDefault();
        expandedFrameSources[source] = !expandedFrameSources[source];
        nested.style.display = expandedFrameSources[source] ? '' : 'none';
        frameSourceDisclosures[source].textContent = expandedFrameSources[source] ? '▾' : '▸';
      });
    });
  }

  function frameSourceRow(source) {
    const row = document.createElement('label');
    row.className = 'lp-row ms-row';
    const disclosure = document.createElement('button');
    disclosure.className = 'ms-disclosure';
    disclosure.title = 'the frames of ' + source;
    disclosure.textContent = expandedFrameSources[source] ? '▾' : '▸';
    frameSourceDisclosures[source] = disclosure;
    const box = document.createElement('input');
    box.type = 'checkbox';
    frameSourceBoxes[source] = box;
    box.addEventListener('change', function () {
      const ids = FrameAxes.framesOfSource(RobotView.frames(), source)
        .map(function (frame) { return frame.id; });
      RobotView.setHiddenFrames(
        FrameAxes.setSourceHidden(window.localStorage, source, !box.checked, ids));
      refreshFrameTicks();
    });
    row.appendChild(disclosure);
    row.appendChild(box);
    row.appendChild(document.createTextNode(source));
    return row;
  }

  function frameSourceRows(source) {
    frameBoxes[source] = {};
    return FrameAxes.framesOfSource(RobotView.frames(), source).map(function (frame) {
      const row = document.createElement('label');
      row.className = 'lp-row ms-row';
      const box = document.createElement('input');
      box.type = 'checkbox';
      frameBoxes[source][frame.id] = box;
      box.addEventListener('change', function () {
        RobotView.setHiddenFrames(FrameAxes.setFrameHidden(
          window.localStorage, frame.id, !box.checked, source));
        refreshFrameTicks();
      });
      row.appendChild(box);
      row.appendChild(document.createTextNode(frame.name));
      return row;
    });
  }

  // Re-read every tick box from the stored state: one frame going off can turn its
  // source's box from ticked to partial, and ticking a source clears the frames
  // under it, so the whole tree is refreshed rather than the row that was clicked.
  function refreshFrameTicks() {
    const hidden = FrameAxes.hidden(window.localStorage);
    const frames = RobotView.frames();
    Object.keys(frameSourceBoxes).forEach(function (source) {
      const state = FrameAxes.sourceState(frames, source, hidden);
      const box = frameSourceBoxes[source];
      box.checked = state !== FrameAxes.SourceState.NONE;
      box.indeterminate = state === FrameAxes.SourceState.SOME;
      const boxes = frameBoxes[source] || {};
      Object.keys(boxes).forEach(function (id) {
        boxes[id].checked = !hidden.sources[source] && !hidden.frames[id];
      });
    });
  }

  frameGearEl.addEventListener('click', function (event) {
    event.preventDefault();
    frameSettingsEl.classList.toggle('hidden');
    if (!frameSettingsEl.classList.contains('hidden')) {
      renderFrameSettings(FrameAxes.settings(window.localStorage));
    }
  });
  framesLayerEl.addEventListener('change', function () {
    RobotView.setFramesVisible(
      FrameAxes.setVisible(window.localStorage, framesLayerEl.checked).visible);
  });
  applyFrameSettings(FrameAxes.settings(window.localStorage));

  bindLayer('lyr-labels', 'setLabelsAlways');
  bindLayer('lyr-floor', 'setFloorVisible');
  const autoLiveEl = $('lyr-auto-live');
  autoLiveEl.checked = autoLiveOn();
  autoLiveEl.addEventListener('change', function () {
    setAutoLive(autoLiveEl.checked);
    if (autoLiveEl.checked) probeLive();     // take effect now, not at the next probe tick
  });
  RobotView.onReady(function () {
    const legend = $('lp-legend');
    const scene = RobotView.getScene();
    if (!legend || !scene || !scene.objects) return;
    legend.innerHTML = scene.objects.map(function (entry) {
      return '<div class="li"><span class="dot" style="background:' + entry.color + '"></span>' +
        entry.id.replace(/_/g, ' ').replace(/[&<>]/g, '') + '</div>';
    }).join('');
  });

  return {
    destroy: function () {
      running = false;                       // stops the requestAnimationFrame loop
      clearInterval(probeTimer);
      clearInterval(recordingProbeTimer);
      if (liveTimer) { clearInterval(liveTimer); liveTimer = null; }
      containerObserver.disconnect();
      window.removeEventListener('resize', resize);
      renderer.dispose();
    },
  };
});
